#include <iostream>
#include <functional>
using namespace std;

enum class State { CLOSED, OPEN, HALF_OPEN };

class CircuitBreaker {
    State state = State::CLOSED;
    int failures = 0, threshold;
public:
    CircuitBreaker(int t) : threshold(t) {}

    bool call(function<int()> fn) {
        if (state == State::OPEN) {
            cout << "Circuit OPEN - rejecting" << endl;
            return false;
        }
        int result = fn();
        if (result < 0) {
            failures++;
            cout << "Failure " << failures << "/" << threshold << endl;
            if (failures >= threshold) {
                state = State::OPEN;
                cout << "Circuit -> OPEN" << endl;
            }
            return false;
        }
        failures = 0;
        cout << "Success, circuit -> CLOSED" << endl;
        return true;
    }

    void halfOpen() { state = State::HALF_OPEN; cout << "Circuit -> HALF_OPEN" << endl; }
};

int main() {
    CircuitBreaker cb(3);
    auto fail = []() -> int { return -1; };
    auto ok = []() -> int { return 200; };
    cb.call(ok); cb.call(ok);
    cb.call(fail); cb.call(fail); cb.call(fail);
    cb.halfOpen();
    cb.call(ok);
    return 0;
}
